const $=id=>document.getElementById(id),make=(t,s)=>{const n=document.createElement(t);if(s!==undefined)n.textContent=s;return n;};
const num=x=>Number(x).toLocaleString('de-AT',{maximumFractionDigits:2});
let token=new URLSearchParams(location.hash.slice(1)).get('token');if(token)history.replaceState(null,'',location.pathname);
const say=s=>$('feedback').textContent=s;
let requestedEmail='';
let leagueState=null;
const chartColors=['#c7f36b','#56c8ff','#ff9f43','#e879f9','#facc15','#fb7185','#67e8f9','#a78bfa'];
const svgNode=(tag,attrs={},label)=>{const n=document.createElementNS('http://www.w3.org/2000/svg',tag);Object.entries(attrs).forEach(([k,v])=>n.setAttribute(k,v));if(label!==undefined)n.textContent=label;return n;};
function drawChart(s,zoom=1){const svg=$('standings-chart'),legend=$('chart-legend'),played=s.games.filter(g=>g.complete);svg.replaceChildren();legend.replaceChildren();if(!played.length){svg.setAttribute('viewBox','0 0 680 180');svg.style.width='680px';svg.append(svgNode('text',{x:340,y:92,'text-anchor':'middle',class:'chart-empty'},'Noch keine Spiele erfasst.'));return;}const margin={left:58,right:28,top:24,bottom:52},height=390,gap=72*zoom,width=Math.max(680,margin.left+margin.right+played.length*gap),plotHeight=height-margin.top-margin.bottom,maxPoints=Math.max(1,...played.flatMap(g=>g.cumulative)),step=maxPoints<=10?2:maxPoints<=25?5:maxPoints<=50?10:Math.ceil(maxPoints/50)*10,top=Math.ceil(maxPoints/step)*step,x=i=>margin.left+i*gap,y=v=>margin.top+plotHeight-(v/top)*plotHeight;svg.setAttribute('viewBox',`0 0 ${width} ${height}`);svg.setAttribute('width',width);svg.setAttribute('height',height);svg.style.width=width+'px';svg.style.height=height+'px';for(let value=0;value<=top;value+=step){const yy=y(value);svg.append(svgNode('line',{x1:margin.left,y1:yy,x2:width-margin.right,y2:yy,class:'chart-grid'}),svgNode('text',{x:margin.left-10,y:yy+4,'text-anchor':'end',class:'chart-label'},num(value)));}svg.append(svgNode('line',{x1:margin.left,y1:margin.top,x2:margin.left,y2:height-margin.bottom,class:'chart-axis'}),svgNode('line',{x1:margin.left,y1:height-margin.bottom,x2:width-margin.right,y2:height-margin.bottom,class:'chart-axis'}));const gameIds=[0,...played.map(g=>g.id)];gameIds.forEach((id,i)=>{const xx=x(i);svg.append(svgNode('line',{x1:xx,y1:height-margin.bottom,x2:xx,y2:height-margin.bottom+6,class:'chart-axis'}),svgNode('text',{x:xx,y:height-margin.bottom+23,'text-anchor':'middle',class:'chart-label'},String(id)));});svg.append(svgNode('text',{x:(margin.left+width-margin.right)/2,y:height-7,'text-anchor':'middle',class:'chart-axis-title'},'Spiel'));s.players.forEach((name,p)=>{const values=[0,...played.map(g=>g.cumulative[p])],points=values.map((v,i)=>`${x(i)},${y(v)}`).join(' '),color=chartColors[p%chartColors.length],line=svgNode('polyline',{points,fill:'none',stroke:color,'stroke-width':3,'stroke-linejoin':'round','stroke-linecap':'round',class:'chart-line'});line.append(svgNode('title',{},name));svg.append(line);values.forEach((v,i)=>{const dot=svgNode('circle',{cx:x(i),cy:y(v),r:4,fill:color,class:'chart-dot'});dot.append(svgNode('title',{},`${name} · Spiel ${gameIds[i]}: ${num(v)} Punkte`));svg.append(dot);});const item=make('span');item.className='legend-item';const swatch=make('i');swatch.style.background=color;item.append(swatch,make('span',name));legend.append(item);});}
async function api(path,data){const r=await fetch('/api/'+path,{method:data===undefined?'GET':'POST',credentials:'same-origin',headers:data===undefined?{}:{'Content-Type':'application/json'},body:data===undefined?undefined:JSON.stringify(data)});const v=await r.json();if(!r.ok){const e=Error(v.error||'Anfrage fehlgeschlagen');e.status=r.status;throw e;}return v;}
async function load(){const s=await api('league');leagueState=s;$('login-panel').hidden=true;$('league-panel').hidden=false;$('status').textContent='Deine Liga · Nur für eingeladene Mitglieder';$('identity').textContent=s.me.email+' · '+({owner:'Besitzer',manager:'Manager',member:'Mitglied'}[s.me.role]);const manages=['owner','manager'].includes(s.me.role);$('new-game').hidden=!manages||!s.game;
 $('standings').replaceChildren();s.players.map((name,i)=>({name,points:s.totals[i]})).sort((a,b)=>b.points-a.points||a.name.localeCompare(b.name)).forEach(p=>{const row=make('div');row.className='standing';row.append(make('span',(1+s.totals.filter(x=>x>p.points+1e-9).length)+'. '+p.name),make('strong',num(p.points)));$('standings').append(row);});
 drawChart(s,Number($('chart-zoom').value)/100);
 $('games').replaceChildren();s.games.forEach(g=>{const item=make('article');item.className='history-item';item.append(make('h3',g.date+' · Spiel '+g.id),make('p',g.complete?s.players.map((name,i)=>g.base[i]===''?null:name+': '+num(g.base[i])).filter(Boolean).join(' · '):'Noch nicht gespielt'),make('small',g.mode+' · Grundpunkte'));if(manages&&g.complete){const a=make('a','Ergebnis korrigieren');a.href='/entry?game='+g.id;item.append(make('br'),a);}$('games').append(item);});
 $('owner-panel').hidden=s.me.role!=='owner';$('audit-panel').hidden=!manages;$('recover').hidden=s.me.role!=='owner'||!s.writeBlocked;if(s.writeBlocked)say('Eine Änderung muss vom Ligabesitzer geprüft werden. Weitere Schreibvorgänge sind gesperrt.');
 if(s.me.role==='owner')await members();if(manages)await audit();
}
async function members(){const v=await api('members');$('members').replaceChildren();v.members.forEach(m=>{const d=make('div');d.className='history-item';d.append(make('h3',m.email),make('p',m.status));if(m.role==='owner')d.append(make('span','Besitzer'));else{const role=make('select');role.setAttribute('aria-label','Rolle für '+m.email);role.append(new Option('Mitglied','member'),new Option('Manager','manager'));role.value=m.role;const save=make('button','Rolle speichern'),revoke=make('button',m.status==='revoked'?'Zugang wieder freigeben':'Zugang entziehen'),resend=make('button','Einladung erneut senden'),remove=make('button','Entfernen');[save,revoke,resend,remove].forEach(b=>b.type='button');save.className=revoke.className=resend.className='secondary';remove.className='danger';const refresh=async message=>{await members();await audit();say(message);};const update=async status=>{try{const result=await api('member',{email:m.email,role:role.value,status});await refresh(result.message);}catch(e){say(e.message);}};save.onclick=()=>update(m.status==='revoked'?'revoked':'active');revoke.onclick=()=>update(m.status==='revoked'?'active':'revoked');resend.disabled=m.status==='revoked';resend.onclick=async()=>{try{const result=await api('resend-invite',{email:m.email});await refresh(result.message);}catch(e){say(e.message);}};remove.onclick=async()=>{if(!confirm('Zugang für '+m.email+' wirklich entfernen?'))return;try{const result=await api('remove-member',{email:m.email});await refresh(result.message);}catch(e){say(e.message);}};d.append(role,save,revoke,resend,remove);}$('members').append(d);});$('join-link').value=v.joinUrl;$('qr').hidden=v.joinUrl!=='https://commander-league-demo.jakobweber.chatgpt.site/';}
async function audit(){const v=await api('audit');$('audit').replaceChildren();if(!v.events.length)$('audit').append(make('p','Noch keine Änderungen.'));const labels={record_result:'Ergebnis erfasst',correct_result:'Ergebnis korrigiert',invite:'Mitglied eingeladen',invite_email:'Einladung erneut versendet',membership:'Zugang geändert',membership_remove:'Zugang entfernt',resolve_write:'Speicherstatus geklärt'};v.events.forEach(a=>{const d=make('article');d.className='history-item';d.append(make('h3',(labels[a.action]||a.action)+' · '+a.target),make('p',a.actor+' · '+new Date(a.created*1000).toLocaleString('de-AT')+' · '+a.status));const detail=make('details');detail.append(make('summary','Vorher / Nachher'),make('pre',a.before_json+'\n→\n'+a.after_json));d.append(detail);$('audit').append(d);});}
$('login-form').onsubmit=async e=>{e.preventDefault();$('login-button').disabled=true;$('request-panel').hidden=true;try{const address=$('email').value.trim();const result=await api('login',{email:address});say(result.message);if(result.registered===false){requestedEmail=address;$('request-panel').hidden=false;}else requestedEmail='';}catch(e){say(e.message);}finally{$('login-button').disabled=false;}};
$('email').oninput=()=>{$('request-panel').hidden=true;requestedEmail='';};
$('request-invite').onclick=async()=>{if(!requestedEmail)return;$('request-invite').disabled=true;try{const result=await api('request-invite',{email:requestedEmail});say(result.message);$('request-panel').hidden=true;requestedEmail='';}catch(e){say(e.message);}finally{$('request-invite').disabled=false;}};
$('chart-zoom').oninput=()=>{if(!leagueState)return;const scroll=$('chart-scroll'),ratio=scroll.scrollWidth>scroll.clientWidth?scroll.scrollLeft/(scroll.scrollWidth-scroll.clientWidth):0;drawChart(leagueState,Number($('chart-zoom').value)/100);requestAnimationFrame(()=>{scroll.scrollLeft=ratio*Math.max(0,scroll.scrollWidth-scroll.clientWidth);});};
$('confirm').onclick=async()=>{$('confirm').disabled=true;try{await api('verify',{token});token=null;await load();say('Angemeldet.');}catch(e){say(e.message);$('login-form').hidden=false;}finally{$('confirm').hidden=true;}};
$('logout').onclick=async()=>{try{await api('logout',{});location.reload();}catch(e){say(e.message);}};
$('invite-form').onsubmit=async e=>{e.preventDefault();try{say((await api('members',{email:$('invite-email').value,role:$('invite-role').value})).message);$('invite-email').value='';await members();await audit();}catch(e){say(e.message);}};
$('copy').onclick=async()=>{try{await navigator.clipboard.writeText($('join-link').value);say('Link kopiert.');}catch{say('Bitte den Link im Feld markieren und kopieren.');}};
$('recover').onclick=async()=>{try{say((await api('recover',{})).message);await load();}catch(e){say(e.message);}};
(async()=>{if(token){$('login-form').hidden=true;$('confirm').hidden=false;$('status').textContent='Anmeldelink erhalten · Bitte bestätigen.';return;}try{await load();}catch(e){$('status').textContent=e.status===401?'Nur für eingeladene Mitglieder.':'Die Live-Verbindung wird noch eingerichtet. Die Demo ist bereits verfügbar.';try{const s=await api('status');$('login-button').disabled=!s.configured;}catch{$('login-button').disabled=true;}}})();
